package com.match.account.service;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.match.account.persistence.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*;
@Service public class AccountTemplateService { private final AccountTemplateMapper mapper; private final ObjectMapper json; public AccountTemplateService(AccountTemplateMapper mapper,ObjectMapper json){this.mapper=mapper;this.json=json;} public List<Map<String,Object>> list(){List<Map<String,Object>> out=new ArrayList<>();for(AccountTemplateRecord r:mapper.selectAllOrdered()){Map<String,Object> v=new LinkedHashMap<>();v.put("templateId",r.getTemplateId());v.put("templateName",r.getTemplateName());v.put("customFields",parse(r.getCustomFields()));v.put("requireProfile",Boolean.TRUE.equals(r.getRequireProfile()));out.add(v);}return out;} @Transactional public Map<String,Object> save(String name,Map<String,String> fields,boolean require,int actor){if(name==null||name.trim().isEmpty())throw new IllegalArgumentException("模板名称不能为空");AccountTemplateRecord r=new AccountTemplateRecord();r.setTemplateId(UUID.randomUUID().toString());r.setTemplateName(name.trim());try{r.setCustomFields(json.writeValueAsString(fields==null?Collections.emptyMap():fields));}catch(Exception e){throw new IllegalArgumentException("模板字段无效");}r.setRequireProfile(require);r.setCreatedBy(actor);r.setCreatedAt(LocalDateTime.now());mapper.insert(r);return list().stream().filter(x->r.getTemplateId().equals(x.get("templateId"))).findFirst().orElseThrow(IllegalStateException::new);} private Map<String,String> parse(String value){try{return json.readValue(value==null?"{}":value,new TypeReference<Map<String,String>>(){});}catch(Exception e){return Collections.emptyMap();}} }
